{
  "name": "oc-stats-tui",
  "version": "0.2.0",
  "description": "A colorful usage, cost and latency dashboard for OpenCode's terminal UI.",
  "license": "MIT",
  "author": "oc-stats contributors",
  "type": "module",
  "homepage": "https://github.com/rbhgaston/oc-stats#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/rbhgaston/oc-stats.git"
  },
  "bugs": {
    "url": "https://github.com/rbhgaston/oc-stats/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "plugin",
    "tui",
    "usage",
    "stats",
    "dashboard",
    "cost",
    "spend",
    "tokens",
    "cache",
    "latency",
    "observability"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "exports": {
    "./tui": "./tui.tsx"
  },
  "files": [
    "tui.tsx",
    "sidebar.tsx",
    "data.ts",
    "format.ts",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.2.5"
  },
  "devDependencies": {
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "engines": {
    "node": "^22.13.0 || >=23.4.0"
  }
}
